INSERT INTO vi_business_base (company_id, code, name, kind, capital_basis, driver1_label, driver1_unit, driver2_label, driver2_unit, driver_scale, boundary, sort) VALUES ((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'B1', '长江干流水电', '经营', '企业', NULL, NULL, NULL, NULL, NULL, '三峡、葛洲坝、溪洛渡、向家坝、乌东德、白鹤滩六座电站的发电与售电；对外持股（国投电力、川投能源等）不在这里，在资产负债桥按账面计。', 1) ON CONFLICT (company_id, code) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, capital_basis = EXCLUDED.capital_basis, driver1_label = EXCLUDED.driver1_label, driver1_unit = EXCLUDED.driver1_unit, driver2_label = EXCLUDED.driver2_label, driver2_unit = EXCLUDED.driver2_unit, driver_scale = EXCLUDED.driver_scale, boundary = EXCLUDED.boundary, sort = EXCLUDED.sort;
