INSERT INTO vi_judgment_base (company_id, code, title, status, judgment, transmission, parameter, change_threshold) VALUES ((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'J-IC', '期初投入资本与资产负债桥（统一估值引擎）', '已形成建议', '2026-06-30 归母权益 2,161.3 亿元，减去资产负债桥里按账面计的项目净额 -2,018.8 亿元（货币资金、带息负债、对外持股（账面价值）、少数股东权益；负数＝负债多于资产），得到经营业务的期初投入资本 4,180.1 亿元。业务资本和资产负债桥合起来正好是报表的归母权益，没有重复或遗漏（自动检查 V09 对账）。', '投入资本是资产价值（未填重置成本时）和 ROIC 的分母；资本增加从自由现金流里扣。', '估值假设·期初投入资本；资产负债桥 N 项', '新的半年报或年报出来后，按同一口径更新截至日与金额。') ON CONFLICT (company_id, code) DO UPDATE SET title = EXCLUDED.title, status = EXCLUDED.status, judgment = EXCLUDED.judgment, transmission = EXCLUDED.transmission, parameter = EXCLUDED.parameter, change_threshold = EXCLUDED.change_threshold;
INSERT INTO vi_judgment_base (company_id, code, title, status, judgment, transmission, parameter, change_threshold) VALUES ((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'J-PROB', '情景概率 25% / 50% / 25%（待确认）', '已形成建议', '还没有逐一论证情景概率，先按悲观 25%、基准 50%、乐观 25% 给出概率加权价值；要改时写清楚为什么某一情景更可能。', '只影响概率加权每股价值，不影响各情景本身。', '情景·情景概率', '有证据表明某一情景的可能性明显更高或更低。') ON CONFLICT (company_id, code) DO UPDATE SET title = EXCLUDED.title, status = EXCLUDED.status, judgment = EXCLUDED.judgment, transmission = EXCLUDED.transmission, parameter = EXCLUDED.parameter, change_threshold = EXCLUDED.change_threshold;
INSERT INTO vi_judgment_base (company_id, code, title, status, judgment, transmission, parameter, change_threshold) VALUES ((SELECT id FROM vi_company_base WHERE code = '600900.SH'), 'J-TAX', '所得税率路径', '已形成建议', '沿用旧逐年假设：2026 年 16.3%，2027 年 17.0%，2028 年起 17.5%（部分电站税收优惠到期）。三季报核对后的修改见待办 Q11。', '税后经营利润＝经营利润×(1−税率)。', '估值假设·税率', '税收优惠到期时间或适用税率有公告变化。') ON CONFLICT (company_id, code) DO UPDATE SET title = EXCLUDED.title, status = EXCLUDED.status, judgment = EXCLUDED.judgment, transmission = EXCLUDED.transmission, parameter = EXCLUDED.parameter, change_threshold = EXCLUDED.change_threshold;
